var item_selector_modal_component_default = `<div class="modal-body">\r
  <p class="lead text-center mb-1">Item selector</p>\r
\r
  <form [formGroup]="searchService.queryForm">\r
    <div class="row">\r
      <ng-container [formGroup]="searchService.fields">\r
        <div class="form-group col-3">\r
          <input [formControlName]="'entry'" type="number" class="form-control form-control-sm" id="entry" placeholder="Entry" />\r
        </div>\r
        <div class="form-group col-5">\r
          <input [formControlName]="'name'" class="form-control form-control-sm" id="name" placeholder="Name" />\r
        </div>\r
      </ng-container>\r
      <div class="form-group col-2">\r
        <input [formControlName]="'limit'" class="form-control form-control-sm" id="limit" placeholder="Unlimited" />\r
      </div>\r
      <div class="col-2">\r
        <button id="search-btn" class="btn btn-primary btn-sm" [disabled]="searchService.queryForm.invalid" (click)="onSearch()">\r
          <i class="fa fa-search"></i> {{ 'SEARCH' | translate }}\r
        </button>\r
      </div>\r
    </div>\r
    <keira-highlightjs-wrapper [code]="searchService.query" />\r
  </form>\r
\r
  @if (searchService.rows) {\r
    <div>\r
      <ngx-datatable\r
        class="bootstrap table table-striped text-center datatable-select highlight-select datatable-icon-list"\r
        [rows]="searchService.rows"\r
        [headerHeight]="DTCFG.headerHeight"\r
        [footerHeight]="DTCFG.footerHeight"\r
        [columnMode]="DTCFG.columnMode"\r
        [rowHeight]="DTCFG.rowHeightWithIcon"\r
        [limit]="DTCFG.limit"\r
        [selectionType]="DTCFG.selectionType"\r
        (select)="onSelect($event)"\r
      >\r
        <ngx-datatable-column [minWidth]="42" [maxWidth]="42" [sortable]="false">\r
          <ng-template let-row="row" ngx-datatable-cell-template>\r
            <keira-icon [itemDisplayId]="row.displayid" />\r
          </ng-template>\r
        </ngx-datatable-column>\r
        <ngx-datatable-column [name]="'entry' | fieldLabel">\r
          <ng-template let-row="row" ngx-datatable-cell-template>\r
            {{ row.entry }}\r
          </ng-template>\r
        </ngx-datatable-column>\r
        <ngx-datatable-column [name]="'name' | fieldLabel" prop="name" />\r
      </ngx-datatable>\r
    </div>\r
  }\r
</div>\r
\r
<div class="modal-footer">\r
  <button type="button" class="btn btn-danger" id="modal-cancel-btn" (click)="onCancel()" [translate]="'CANCEL'"></button>\r
  <button type="button" class="btn btn-success" id="modal-select-btn" (click)="onSave()" [translate]="'SELECT'"></button>\r
</div>\r
`;

