async function findRaceGenderOptions(race, gender) {
  const raceGender = race * 2 - 1 + gender;
  const options = await fetch(`${CONTENT_WOTLK}meta/charactercustomization/${raceGender}.json`).then((response) => response.json());
  if (options.data) {
    return options.data;
  }
  return options;
}
