var select_item_component_default = `<keira-top-bar [selected]="handlerService.selected" [selectedName]="handlerService.selectedName" [isNew]="handlerService.isNew" />\r
\r
<div class="container-fluid">\r
  <div class="content-block">\r
    <keira-create\r
      [entityTable]="entityTable"\r
      [entityIdField]="entityIdField"\r
      [customStartingId]="customStartingId"\r
      [handlerService]="handlerService"\r
      [queryService]="queryService"\r
    />\r
  </div>\r
\r
  <div class="content-block">\r
    <p class="lead" [translate]="'SELECT_EXISTING'"></p>\r
    <form [formGroup]="selectService.queryForm">\r
      <div class="row">\r
        <ng-container [formGroup]="selectService.fields">\r
          <div class="form-group col-sm-6 col-md-4 col-lg-3 col-xl-2">\r
            <input [formControlName]="'entry'" type="number" class="form-control form-control-sm" id="search-id" placeholder="Item ID" />\r
          </div>\r
          <div class="form-group col-sm-6 col-md-4 col-lg-3 col-xl-3">\r
            <input [formControlName]="'name'" class="form-control form-control-sm" id="name" placeholder="Item name" />\r
          </div>\r
        </ng-container>\r
        <div class="form-group col-sm-6 col-md-4 col-lg-3 col-xl-2">\r
          <input [formControlName]="'limit'" class="form-control form-control-sm" id="limit" placeholder="Limit" />\r
        </div>\r
        <div class="mb-2 col-sm-6 col-md-4 col-lg-3 col-xl-2">\r
          <button id="search-btn" class="btn btn-primary btn-sm" [disabled]="selectService.queryForm.invalid" (click)="onSearch()">\r
            <i class="fa fa-search"></i> {{ 'SEARCH' | translate }}\r
          </button>\r
        </div>\r
      </div>\r
      <keira-highlightjs-wrapper [code]="selectService.query" />\r
    </form>\r
\r
    @if (selectService.rows) {\r
      <div>\r
        <ngx-datatable\r
          class="bootstrap table table-striped text-center datatable-select datatable-icon-list"\r
          [rows]="selectService.rows"\r
          [headerHeight]="DTCFG.headerHeight"\r
          [footerHeight]="DTCFG.footerHeight"\r
          [columnMode]="DTCFG.columnMode"\r
          [rowHeight]="DTCFG.rowHeightWithIcon"\r
          [limit]="DTCFG.limit"\r
          [selectionType]="DTCFG.selectionType"\r
          (select)="selectService.onSelect($event)"\r
          [offset]="selectService.pageOffset"\r
          (page)="onPage($event)"\r
        >\r
          <ngx-datatable-column [minWidth]="42" [maxWidth]="42" [sortable]="false">\r
            <ng-template let-row="row" ngx-datatable-cell-template>\r
              <keira-icon [itemDisplayId]="row.displayid" />\r
            </ng-template>\r
          </ngx-datatable-column>\r
          <ngx-datatable-column [name]="'entry' | fieldLabel">\r
            <ng-template let-row="row" ngx-datatable-cell-template>\r
              {{ row.entry }}\r
            </ng-template>\r
          </ngx-datatable-column>\r
          <ngx-datatable-column [name]="'name' | fieldLabel" prop="name" [minWidth]="60">\r
            <ng-template let-row="row" ngx-datatable-cell-template>\r
              <div>\r
                <b [class]="'item-quality-q' + row.Quality">{{ row.name }}</b>\r
              </div>\r
            </ng-template>\r
          </ngx-datatable-column>\r
          <ngx-datatable-column [name]="'displayid' | fieldLabel" prop="displayid" />\r
          <ngx-datatable-column [name]="'class' | fieldLabel" prop="class" />\r
          <ngx-datatable-column [name]="'subclass' | fieldLabel" prop="subclass" />\r
          <ngx-datatable-column [name]="'Quality' | fieldLabel" prop="Quality" />\r
          <ngx-datatable-column [name]="'ItemLevel' | fieldLabel" prop="ItemLevel" />\r
          <ngx-datatable-column [name]="'RequiredLevel' | fieldLabel" prop="RequiredLevel" />\r
        </ngx-datatable>\r
      </div>\r
    }\r
  </div>\r
</div>\r
`;

