var creature_questender_component_default = `<keira-top-bar [selected]="handlerService.selected" [selectedName]="handlerService.selectedName" [isNew]="handlerService.isNew" />\r
\r
<div class="container-fluid editor-with-preview" [class.show-preview]="questPreviewService.showPreview">\r
  @if (editorService.loading) {\r
    <span [translate]="'LOADING'"></span>\r
  }\r
\r
  @if (editorService.form && !!editorService.loadedEntityId && !editorService.loading) {\r
    <div>\r
      <div class="content-block">\r
        <keira-query-output\r
          [docUrl]="docUrl"\r
          [isNew]="editorService.isNew"\r
          [diffQuery]="editorService.diffQuery"\r
          [fullQuery]="editorService.fullQuery"\r
          [error]="editorService.error"\r
          [entityTable]="editorService.entityTable"\r
          [editorService]="editorService"\r
          (executeQuery)="save($event)"\r
        />\r
      </div>\r
      <div class="content-block">\r
        <form [formGroup]="editorService.form" class="form-group edit-form">\r
          <div class="row">\r
            <div class="form-group col-12 col-sm-6 col-md-4 col-lg-4 col-xl-4">\r
              <label class="control-label" for="id">{{ 'id' | fieldLabel }}</label>\r
              <keira-creature-selector-btn\r
                [control]="editorService.form.controls.id"\r
                [disabled]="editorService.form.controls.id.disabled"\r
                [config]="{ name: 'id' }"\r
              />\r
              <i class="fas fa-info-circle ms-1" placement="auto" [tooltip]="'creature_template.entry' | translate"></i>\r
              <input [formControlName]="'id'" id="id" type="number" class="form-control form-control-sm" />\r
            </div>\r
            <div class="col-12 form-error" [hidden]="editorService.isFormIdUnique()">\r
              <i class="fas fa-exclamation-triangle"></i>\r
              <span [innerHTML]="'UNIQUE' | translate: { ENTITY_SECOND_ID_FIELD: editorService.entitySecondIdField }"></span>\r
            </div>\r
          </div>\r
        </form>\r
        <div class="row">\r
          <div class="col-12">\r
            <keira-editor-buttons\r
              [selectedRowId]="editorService.selectedRowId"\r
              (deleteSelectedRow)="editorService.deleteSelectedRow()"\r
              (addNewRow)="editorService.addNewRow()"\r
              (duplicateRow)="editorService.addNewRow(true)"\r
            />\r
            <ngx-datatable\r
              id="editor-table"\r
              class="bootstrap table table-striped text-center datatable-select"\r
              [rows]="editorService.newRows"\r
              [headerHeight]="DTCFG.headerHeight"\r
              [footerHeight]="DTCFG.footerHeight"\r
              [columnMode]="DTCFG.columnMode"\r
              [rowHeight]="DTCFG.rowHeight"\r
              [selectionType]="DTCFG.selectionType"\r
              (select)="editorService.onRowSelection($event)"\r
              (keydown.delete)="editorService.deleteSelectedRow()"\r
            >\r
              <ngx-datatable-column [minWidth]="30" [maxWidth]="30" [sortable]="false">\r
                <ng-template let-row="row" ngx-datatable-cell-template>\r
                  <i [hidden]="!editorService.isRowSelected(row)" class="fas fa-chevron-right"></i>\r
                </ng-template>\r
              </ngx-datatable-column>\r
              <ngx-datatable-column [name]="'id' | fieldLabel" prop="id" [minWidth]="80" [maxWidth]="150" />\r
              <ngx-datatable-column [name]="'name' | fieldLabel" [minWidth]="200">\r
                <ng-template let-row="row" ngx-datatable-cell-template>\r
                  {{ editorService.queryService.getCreatureNameById(row.id) | async }}\r
                </ng-template>\r
              </ngx-datatable-column>\r
            </ngx-datatable>\r
          </div>\r
        </div>\r
      </div>\r
      <keira-quest-preview />\r
    </div>\r
  }\r
</div>\r
`;

