var page_text_component_default = `<keira-top-bar [selected]="handlerService.selected" [selectedName]="handlerService.selectedName" [isNew]="handlerService.isNew" />\r
\r
<div class="container-fluid">\r
  @if (editorService.loading) {\r
    <span [translate]="'LOADING'"></span>\r
  }\r
\r
  @if (editorService.form && !!editorService.loadedEntityId && !editorService.loading) {\r
    <div>\r
      <div class="content-block">\r
        <keira-query-output\r
          [docUrl]="docUrl"\r
          [isNew]="editorService.isNew"\r
          [diffQuery]="editorService.diffQuery"\r
          [fullQuery]="editorService.fullQuery"\r
          [error]="editorService.error"\r
          [entityTable]="editorService.entityTable"\r
          [editorService]="editorService"\r
          (executeQuery)="save($event)"\r
        />\r
      </div>\r
      <form [formGroup]="editorService.form" class="form-group edit-form">\r
        <div class="content-block">\r
          <div class="row">\r
            <div class="form-group col-12 col-sm-6 col-md-4 col-lg-3 col-xl-2">\r
              <label class="control-label" for="ID">{{ 'ID' | fieldLabel }}</label>\r
              <i class="fas fa-info-circle ms-1" placement="auto" [tooltip]="'OTHER_TEXTS.PAGE_TEXT.ID' | translate"></i>\r
              <input [formControlName]="'ID'" id="ID" type="number" class="form-control form-control-sm" />\r
            </div>\r
            <div class="form-group col-12 col-sm-6 col-md-4 col-lg-3 col-xl-2">\r
              <label class="control-label" for="NextPageID">{{ 'NextPageID' | fieldLabel }}</label>\r
              <i class="fas fa-info-circle ms-1" placement="auto" [tooltip]="'OTHER_TEXTS.PAGE_TEXT.NEXT_PAGE_ID' | translate"></i>\r
              <input [formControlName]="'NextPageID'" id="NextPageID" type="number" class="form-control form-control-sm" />\r
            </div>\r
          </div>\r
          <div class="row">\r
            <div class="form-group col-12">\r
              <label class="control-label" for="Text">{{ 'Text' | fieldLabel }}</label>\r
              <i class="fas fa-info-circle ms-1" placement="auto" [tooltip]="'OTHER_TEXTS.PAGE_TEXT.TEXT' | translate"></i>\r
              <textarea [formControlName]="'Text'" id="Text" class="form-control form-control-sm" rows="10"></textarea>\r
            </div>\r
          </div>\r
        </div>\r
      </form>\r
    </div>\r
  }\r
</div>\r
`;

